1	import React, { useState, useEffect } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import { getEmpresas, criarEmpresa, atualizarEmpresa, removerEmpresa, bloquearEmpresa, atenderSolicitacaoDominio, recusarSolicitacaoDominio } from '../../services/adminService';
4	import { useAuth } from '../../contexts/AuthContext';
5	import { useLocalMode, LocalModeBanner } from '../../contexts/LocalModeContext';
6	
7	const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
8	
9	const AdminNav = ({ active }) => {
10	  const navigate = useNavigate();
11	  const { signOut } = useAuth();
12	  const links = [
13	    { label: 'Dashboard', path: '/admin' },
14	    { label: 'Empresas', path: '/admin/empresas' },
15	    { label: 'Categorias', path: '/admin/categorias' },
16	    { label: 'Tipos',      path: '/admin/tipos-estabelecimento' },
17	    { label: 'Tags',       path: '/admin/tags' },
18	    { label: 'Comissões', path: '/admin/comissoes' },
19	    { label: 'Configurações', path: '/admin/configuracoes' },
20	  ];
21	  return (
22	    <nav className="flex gap-3 items-center">
23	      {links.map((l) => (
24	        <button
25	          key={l.path}
26	          onClick={() => navigate(l.path)}
27	          className={`px-4 py-2 text-sm font-medium rounded-lg ${
28	            active === l.path ? 'text-white bg-blue-600' : 'text-gray-700 hover:bg-gray-100'
29	          }`}
30	        >
31	          {l.label}
32	        </button>
33	      ))}
34	      <button
35	        onClick={async () => { await signOut(); navigate('/customer-registration-login'); }}
36	        className="px-4 py-2 text-sm font-medium text-red-600 hover:bg-red-50 rounded-lg border border-red-200"
37	      >
38	        Sair
39	      </button>
40	    </nav>
41	  );
42	};
43	
44	const Modal = ({ empresa, onClose, onSave }) => {
45	  const [form, setForm] = useState({
46	    name: empresa?.name ?? '',
47	    address: empresa?.address ?? '',
48	    comissao_pct: empresa?.comissao_pct ?? 5,
49	    user_id: empresa?.user_id ?? '',
50	  });
51	  const [salvando, setSalvando] = useState(false);
52	
53	  const handleSubmit = async (e) => {
54	    e.preventDefault();
55	    setSalvando(true);
56	    try {
57	      if (empresa) {
58	        await atualizarEmpresa(empresa.id, form);
59	      } else {
60	        await criarEmpresa(form);
61	      }
62	      onSave();
63	    } catch (err) {
64	      alert(err.message);
65	    } finally {
66	      setSalvando(false);
67	    }
68	  };
69	
70	  return (
71	    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
72	      <div className="bg-white rounded-xl w-full max-w-md p-6">
73	        <h3 className="text-lg font-semibold mb-4">{empresa ? 'Editar Empresa' : 'Nova Empresa'}</h3>
74	        <form onSubmit={handleSubmit} className="space-y-4">
75	          <div>
76	            <label className="block text-sm font-medium text-gray-700 mb-1">Nome *</label>
77	            <input
78	              required
79	              className="w-full border rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
80	              value={form.name}
81	              onChange={(e) => setForm({ ...form, name: e.target.value })}
82	            />
83	          </div>
84	          <div>
85	            <label className="block text-sm font-medium text-gray-700 mb-1">Endereço</label>
86	            <input
87	              className="w-full border rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
88	              value={form.address}
89	              onChange={(e) => setForm({ ...form, address: e.target.value })}
90	            />
91	          </div>
92	          <div>
93	            <label className="block text-sm font-medium text-gray-700 mb-1">Comissão plataforma (%)</label>
94	            <input
95	              type="number"
96	              min="0"
97	              max="100"
98	              step="0.5"
99	              className="w-full border rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
100	              value={form.comissao_pct}
101	              onChange={(e) => setForm({ ...form, comissao_pct: parseFloat(e.target.value) })}
102	            />
103	          </div>
104	          <div>
105	            <label className="block text-sm font-medium text-gray-700 mb-1">
106	              UUID do dono (restaurant_owner)
107	            </label>
108	            <input
109	              className="w-full border rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 font-mono text-xs"
110	              placeholder="xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx"
111	              value={form.user_id}
112	              onChange={(e) => setForm({ ...form, user_id: e.target.value.trim() })}
113	            />
114	            <p className="text-xs text-gray-400 mt-1">
115	              UUID do usuário cadastrado como restaurant_owner. Deixe vazio se não houver dono ainda.
116	            </p>
117	          </div>
118	          <div className="flex gap-3 pt-2">
119	            <button
120	              type="button"
121	              onClick={onClose}
122	              className="flex-1 px-4 py-2 border rounded-lg text-sm font-medium text-gray-700 hover:bg-gray-50"
123	            >
124	              Cancelar
125	            </button>
126	            <button
127	              type="submit"
128	              disabled={salvando}
129	              className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 disabled:opacity-50"
130	            >
131	              {salvando ? 'Salvando...' : 'Salvar'}
132	            </button>
133	          </div>
134	        </form>
135	      </div>
136	    </div>
137	  );
138	};
139	
140	const AdminEmpresas = () => {
141	  const navigate = useNavigate();
142	  const { isLocalMode, localRestaurantId } = useLocalMode() ?? {};
143	  const [empresas, setEmpresas] = useState([]);
144	  const [loading, setLoading] = useState(true);
145	  const [erro, setErro] = useState(null);
146	  const [modal, setModal] = useState(null); // null | 'novo' | empresa_obj
147	
148	  const carregar = async () => {
149	    setLoading(true);
150	    try {
151	      const data = await getEmpresas();
152	      let lista = data.empresas ?? [];
153	      // Modo local: restringe a 1 restaurante
154	      if (isLocalMode && localRestaurantId) {
155	        lista = lista.filter((e) => e.id === localRestaurantId);
156	      }
157	      setEmpresas(lista);
158	    } catch (e) {
159	      setErro(e.message);
160	    } finally {
161	      setLoading(false);
162	    }
163	  };
164	
165	  useEffect(() => { carregar(); }, []);
166	
167	  const handleRemover = async (empresa) => {
168	    if (!confirm(`Remover "${empresa.name}"? Esta ação não pode ser desfeita.`)) return;
169	    try {
170	      await removerEmpresa(empresa.id);
171	      carregar();
172	    } catch (e) {
173	      alert(e.message);
174	    }
175	  };
176	
177	  const handleBloquear = async (empresa) => {
178	    const acao = empresa.bloqueado ? 'desbloquear' : 'bloquear';
179	    if (!confirm(`${acao.charAt(0).toUpperCase() + acao.slice(1)} "${empresa.name}"?`)) return;
180	    try {
181	      await bloquearEmpresa(empresa.id, !empresa.bloqueado);
182	      carregar();
183	    } catch (e) {
184	      alert(e.message);
185	    }
186	  };
187	
188	  const handleAtenderDominio = async (empresa) => {
189	    if (!confirm(`Aprovar domínio "${empresa.custom_domain}" de "${empresa.name}"? Só confirme depois de adicionar o domínio no painel do EasyPanel.`)) return;
190	    try {
191	      await atenderSolicitacaoDominio(empresa.id);
192	      carregar();
193	    } catch (e) {
194	      alert(e.message);
195	    }
196	  };
197	
198	  const handleRecusarDominio = async (empresa) => {
199	    const motivo = prompt(`Motivo da recusa do domínio "${empresa.custom_domain}" (${empresa.name}):`);
200	    if (motivo === null) return;
201	    try {
202	      await recusarSolicitacaoDominio(empresa.id, motivo);
203	      carregar();
204	    } catch (e) {
205	      alert(e.message);
206	    }
207	  };
208	
209	  const solicitacoesDominio = empresas.filter((e) => e.custom_domain_status === 'pendente');
210	
211	  return (
212	    <div className="min-h-screen bg-gray-50">
213	      <LocalModeBanner />
214	      <header className="bg-white border-b px-6 py-4 flex items-center justify-between">
215	        <div>
216	          <h1 className="text-xl font-bold text-gray-900">Painel Dev-Admin</h1>
217	          <p className="text-sm text-gray-500">Gestão de Empresas</p>
218	        </div>
219	        <AdminNav active="/admin/empresas" />
220	      </header>
221	
222	      <main className="p-6 max-w-6xl mx-auto">
223	        <div className="flex items-center justify-between mb-6">
224	          <h2 className="text-lg font-semibold text-gray-900">
225	            Empresas <span className="text-gray-400 font-normal text-sm">({empresas.length})</span>
226	            {solicitacoesDominio.length > 0 && (
227	              <span className="ml-2 inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-amber-100 text-amber-700 align-middle">
228	                {solicitacoesDominio.length} solicitação(ões) de domínio pendente(s)
229	              </span>
230	            )}
231	          </h2>
232	          {!isLocalMode && (
233	            <button
234	              onClick={() => setModal('novo')}
235	              className="px-4 py-2 bg-blue-600 text-white text-sm font-medium rounded-lg hover:bg-blue-700"
236	            >
237	              + Nova Empresa
238	            </button>
239	          )}
240	        </div>
241	
242	        {solicitacoesDominio.length > 0 && (
243	          <div className="mb-6 bg-amber-50 border border-amber-200 rounded-xl p-4">
244	            <h3 className="text-sm font-semibold text-amber-800 mb-3">Solicitações de domínio personalizado</h3>
245	            <div className="space-y-2">
246	              {solicitacoesDominio.map((e) => (
247	                <div key={e.id} className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 bg-white rounded-lg border border-amber-200 px-3 py-2.5">
248	                  <div>
249	                    <p className="text-sm font-medium text-gray-900">{e.name}</p>
250	                    <p className="text-xs font-mono text-amber-700">{e.custom_domain}</p>
251	                    {e.custom_domain_solicitado_em && (
252	                      <p className="text-[11px] text-gray-400">
253	                        Solicitado em {new Date(e.custom_domain_solicitado_em).toLocaleString('pt-BR')}
254	                      </p>
255	                    )}
256	                  </div>
257	                  <div className="flex gap-2">
258	                    <button
259	                      onClick={() => navigate(`/admin/empresas/${e.id}`)}
260	                      className="px-3 py-1.5 text-xs font-medium text-blue-600 hover:bg-blue-50 rounded-lg border border-blue-200"
261	                    >
262	                      Ver empresa
263	                    </button>
264	                    <button
265	                      onClick={() => handleAtenderDominio(e)}
266	                      className="px-3 py-1.5 text-xs font-medium text-green-700 hover:bg-green-50 rounded-lg border border-green-200"
267	                    >
268	                      Aprovar
269	                    </button>
270	                    <button
271	                      onClick={() => handleRecusarDominio(e)}
272	                      className="px-3 py-1.5 text-xs font-medium text-red-600 hover:bg-red-50 rounded-lg border border-red-200"
273	                    >
274	                      Recusar
275	                    </button>
276	                  </div>
277	                </div>
278	              ))}
279	            </div>
280	          </div>
281	        )}
282	
283	        {erro && (
284	          <div className="mb-4 p-4 bg-red-50 border border-red-200 rounded-lg text-red-700 text-sm">
285	            {erro} — verifique se o backend está rodando.
286	          </div>
287	        )}
288	
289	        {loading ? (
290	          <div className="flex justify-center py-12">
291	            <div className="w-8 h-8 border-4 border-blue-600 border-t-transparent rounded-full animate-spin" />
292	          </div>
293	        ) : (
294	          <div className="bg-white rounded-xl border overflow-x-auto">
295	            {empresas.length === 0 ? (
296	              <div className="p-12 text-center text-gray-400">
297	                <p className="text-lg">Nenhuma empresa cadastrada</p>
298	                <button
299	                  onClick={() => setModal('novo')}
300	                  className="mt-3 text-blue-600 text-sm hover:underline"
301	                >
302	                  Cadastrar primeira empresa
303	                </button>
304	              </div>
305	            ) : (
306	              <table className="w-full text-sm">
307	                <thead>
308	                  <tr className="border-b bg-gray-50">
309	                    <th className="px-2 sm:px-4 py-3 text-left font-medium text-gray-600 hidden sm:table-cell">ID</th>
310	                    <th className="px-2 sm:px-4 py-3 text-left font-medium text-gray-600">Nome</th>
311	                    <th className="px-2 sm:px-4 py-3 text-left font-medium text-gray-600 hidden lg:table-cell">Slug / Link</th>
312	                    <th className="px-2 sm:px-4 py-3 text-left font-medium text-gray-600 hidden md:table-cell">Endereço</th>
313	                    <th className="px-2 sm:px-4 py-3 text-left font-medium text-gray-600">Status</th>
314	                    <th className="px-2 sm:px-4 py-3 text-left font-medium text-gray-600 hidden lg:table-cell">Domínio</th>
315	                    <th className="px-2 sm:px-4 py-3 text-right font-medium text-gray-600 hidden md:table-cell">Comissão</th>
316	                    <th className="px-2 sm:px-4 py-3 text-right font-medium text-gray-600 hidden lg:table-cell">Cadastro</th>
317	                    <th className="px-2 sm:px-4 py-3 w-px whitespace-nowrap"></th>
318	                  </tr>
319	                </thead>
320	                <tbody>
321	                  {empresas.map((e) => (
322	                    <tr key={e.id} className="border-b last:border-0 hover:bg-gray-50">
323	                      <td className="px-2 sm:px-4 py-3 text-gray-400 hidden sm:table-cell">#{e.id}</td>
324	                      <td className="px-2 sm:px-4 py-3 font-medium text-gray-900 max-w-[120px] sm:max-w-none truncate">{e.name}</td>
325	                      <td className="px-2 sm:px-4 py-3 hidden lg:table-cell">
326	                        {e.slug ? (
327	                          <a
328	                            href={`/r/${e.slug}`}
329	                            target="_blank"
330	                            rel="noopener noreferrer"
331	                            className="text-xs text-blue-600 hover:underline font-mono"
332	                          >
333	                            /r/{e.slug}
334	                          </a>
335	                        ) : (
336	                          <span className="text-xs text-gray-400">—</span>
337	                        )}
338	                      </td>
339	                      <td className="px-2 sm:px-4 py-3 text-gray-500 hidden md:table-cell max-w-xs truncate">
340	                        {e.address ?? '—'}
341	                      </td>
342	                      <td className="px-2 sm:px-4 py-3">
343	                        {e.bloqueado ? (
344	                          <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-red-100 text-red-700">
345	                            <span className="w-1.5 h-1.5 rounded-full bg-red-500" /> Bloqueado
346	                          </span>
347	                        ) : (
348	                          <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-700">
349	                            <span className="w-1.5 h-1.5 rounded-full bg-green-500" /> Ativo
350	                          </span>
351	                        )}
352	                      </td>
353	                      <td className="px-2 sm:px-4 py-3 hidden lg:table-cell">
354	                        {e.custom_domain_status === 'pendente' ? (
355	                          <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-amber-100 text-amber-700 font-mono">
356	                            {e.custom_domain} (pendente)
357	                          </span>
358	                        ) : e.custom_domain_status === 'recusado' ? (
359	                          <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-red-100 text-red-700 font-mono">
360	                            {e.custom_domain} (recusado)
361	                          </span>
362	                        ) : e.custom_domain ? (
363	                          <span className="text-xs text-gray-500 font-mono">{e.custom_domain}</span>
364	                        ) : (
365	                          <span className="text-xs text-gray-400">—</span>
366	                        )}
367	                      </td>
368	                      <td className="px-2 sm:px-4 py-3 text-right hidden md:table-cell">
369	                        <span className="inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium bg-orange-100 text-orange-700">
370	                          {e.comissao_pct ?? 5}%
371	                        </span>
372	                      </td>
373	                      <td className="px-2 sm:px-4 py-3 text-right text-gray-400 text-xs hidden lg:table-cell">
374	                        {new Date(e.created_at).toLocaleDateString('pt-BR')}
375	                      </td>
376	                      <td className="px-2 sm:px-4 py-3 w-px whitespace-nowrap">
377	                        <div className="flex gap-1 sm:gap-2 justify-end">
378	                          <button
379	                            onClick={() => navigate(`/admin/empresas/${e.id}`)}
380	                            className="px-3 py-1 text-xs font-medium text-blue-600 hover:bg-blue-50 rounded-lg"
381	                          >
382	                            Ver
383	                          </button>
384	                          <button
385	                            onClick={() => setModal(e)}
386	                            className="px-3 py-1 text-xs font-medium text-gray-600 hover:bg-gray-100 rounded-lg"
387	                          >
388	                            Editar
389	                          </button>
390	                          <button
391	                            onClick={() => handleBloquear(e)}
392	                            className={`px-3 py-1 text-xs font-medium rounded-lg ${
393	                              e.bloqueado
394	                                ? 'text-green-700 hover:bg-green-50'
395	                                : 'text-red-600 hover:bg-red-50'
396	                            }`}
397	                          >
398	                            {e.bloqueado ? 'Desbloquear' : 'Bloquear'}
399	                          </button>
400	                          {!isLocalMode && (
401	                            <button
402	                              onClick={() => handleRemover(e)}
403	                              className="px-3 py-1 text-xs font-medium text-red-600 hover:bg-red-50 rounded-lg"
404	                            >
405	                              Remover
406	                            </button>
407	                          )}
408	                        </div>
409	                      </td>
410	                    </tr>
411	                  ))}
412	                </tbody>
413	              </table>
414	            )}
415	          </div>
416	        )}
417	      </main>
418	
419	      {modal && (
420	        <Modal
421	          empresa={modal === 'novo' ? null : modal}
422	          onClose={() => setModal(null)}
423	          onSave={() => { setModal(null); carregar(); }}
424	        />
425	      )}
426	    </div>
427	  );
428	};
429	
430	export default AdminEmpresas;
