372	  async listarClientes(restaurantId: number, filtros: { busca?: string; limite?: number }) {
373	    // Busca IDs dos clientes vinculados a este restaurante
374	    const { data: crRows, error: crErr } = await this.supabase.client
375	      .from('customer_restaurants')
376	      .select('customer_id')
377	      .eq('restaurant_id', restaurantId);
378	
379	    if (crErr) throw crErr;
380	    const customerIds = (crRows ?? []).map((r) => r.customer_id);
381	    if (customerIds.length === 0) return { clientes: [], total: 0 };
382	
383	    // Busca dados dos clientes com filtro opcional
384	    let q = this.supabase.client
385	      .from('customers')
386	      .select('id, name, email, phone_e164, notes, user_id, created_at')
387	      .in('id', customerIds)
388	      .order('name');
389	
390	    if (filtros.busca) {
391	      q = q.or(`name.ilike.%${filtros.busca}%,email.ilike.%${filtros.busca}%,phone_e164.ilike.%${filtros.busca}%`);
392	    }
393	    if (filtros.limite) q = q.limit(filtros.limite);
394	
395	    const { data: clientes, error: cErr } = await q;
396	    if (cErr) throw cErr;
397	
398	    if (!clientes?.length) return { clientes: [], total: 0 };
399	
400	    // Busca estatísticas de pedidos por cliente neste restaurante
401	    const ids = clientes.map((c) => c.id);
402	    const { data: pedidos } = await this.supabase.client
403	      .from('orders')
404	      .select('customer_id, total, created_at')
405	      .eq('restaurant_id', restaurantId)
406	      .in('customer_id', ids)
407	      .neq('status', 'canceled');
408	
409	    const statsMap: Record<number, { count: number; total: number; ultimo: string | null }> = {};
410	    for (const p of pedidos ?? []) {
411	      if (!statsMap[p.customer_id]) statsMap[p.customer_id] = { count: 0, total: 0, ultimo: null };
412	      statsMap[p.customer_id].count++;
413	      statsMap[p.customer_id].total += parseFloat(p.total);
414	      if (!statsMap[p.customer_id].ultimo || p.created_at > (statsMap[p.customer_id].ultimo as string)) {
415	        statsMap[p.customer_id].ultimo = p.created_at;
416	      }
417	    }
418	
419	    const result = clientes.map((c) => ({
420	      ...c,
421	      pedidos_count: statsMap[c.id]?.count ?? 0,
422	      total_gasto: statsMap[c.id]?.total ?? 0,
423	      ultimo_pedido: statsMap[c.id]?.ultimo ?? null,
424	    }));
425	
426	    return { clientes: result, total: result.length };
427	  }
