481	  async updateEmpresa(
482	    restaurantId: number,
483	    body: { name?: string; address?: string; state?: string; city?: string; neighborhood?: string; cep?: string; logo_url?: string; slug?: string },
484	  ) {
485	    const campos: Record<string, any> = { updated_at: new Date().toISOString() };
486	    if (body.name !== undefined) campos.name = body.name;
487	    if (body.address !== undefined) campos.address = body.address;
488	    if (body.state !== undefined) campos.state = body.state;
489	    if (body.city !== undefined) campos.city = body.city;
490	    if (body.neighborhood !== undefined) campos.neighborhood = body.neighborhood;
491	    if (body.cep !== undefined) campos.cep = body.cep ? body.cep.replace(/\D/g, '') : null;
492	    if (body.logo_url !== undefined) campos.logo_url = body.logo_url;
493	    if (body.slug !== undefined) {
494	      const slug = body.slug.trim().toLowerCase();
495	      if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(slug) || slug.length < 3 || slug.length > 60) {
496	        throw new BadRequestException('Link inválido. Use só letras minúsculas, números e hífen (mín. 3 caracteres), sem começar/terminar com hífen.');
497	      }
498	      campos.slug = slug;
499	    }
500	
501	    const { data, error } = await this.supabase.client
502	      .from('restaurants')
503	      .update(campos)
504	      .eq('id', restaurantId)
505	      .select('id, name, address, state, city, neighborhood, cep, logo_url, slug')
506	      .maybeSingle();
507	
508	    if (error) {
509	      if ((error as any).code === '23505') {
510	        throw new ConflictException('Esse link já está em uso por outro estabelecimento.');
511	      }
512	      throw error;
513	    }
514	
515	    // Geocodifica em background (best-effort) sempre que algum campo de endereço mudou —
516	    // usa o endereço completo (rua + bairro + cidade + estado + cep), não só o campo livre
517	    // "address" sozinho, que sem cidade/estado o Nominatim geocodificava impreciso/errado
518	    // (ex: rua comum sem contexto de cidade cai em outro município, filtro por raio nunca
519	    // encontrava o próprio restaurante). Nunca falha o save do endereço por causa disso.
520	    if (body.address !== undefined || body.state !== undefined || body.city !== undefined || body.neighborhood !== undefined || body.cep !== undefined) {
521	      this.geocodificarEndereco(restaurantId, {
522	        address: data?.address ?? null,
523	        neighborhood: data?.neighborhood ?? null,
524	        city: data?.city ?? null,
525	        state: data?.state ?? null,
526	        cep: data?.cep ?? null,
527	      }).catch(() => {});
528	    }
529	
530	    return data;
531	  }
