785	  // KDS por setor (módulo Salão): tela genérica reaproveitável por impressora/setor
786	  // (cozinha, bar, salgados...) — lista PLANA de itens (não agrupa por mesa/comanda,
787	  // cada item tem sua própria ação de preparo/impressão), ordenada por chegada.
788	  async getKdsSetor(restaurantId: number, impressoraId: number) {
789	    // Itens "pronto" de hoje inteiro também entram — sem isso, um clique errado em
790	    // "Entregue"/"Pronto" faz o item sumir da tela sem chance de desfazer. A tela
791	    // (Cozinha/Produção) que decide mostrar só os últimos N com opção de expandir.
792	    const inicioDoDia = new Date();
793	    inicioDoDia.setHours(0, 0, 0, 0);
794	    const limiteProntos = inicioDoDia.toISOString();
795	    const { data: itens, error } = await this.supabase.client
796	      .from('order_items')
797	      .select('id, quantity, unit_price, observacao, product_id, status, enviado_em, preparando_em, pronto_em, entregue_garcom, order_id, products(name), orders(id, restaurant_id, mesa_id, cliente_mesa_nome, garcom_id, customer_id, status, numero_comanda, motoboy_lat, motoboy_lng, delivery_occurrence, mesas(numero, nome), garcons(nome))')
798	      .eq('impressora_id', impressoraId)
799	      .or(`status.in.(enviado,preparando),and(status.eq.pronto,pronto_em.gte.${limiteProntos})`)
800	      .order('enviado_em', { ascending: true });
801	    if (error) throw error;
802	
803	    const itensValidos = (itens as any[]).filter((i) => i.orders?.restaurant_id === restaurantId);
804	
805	    // Um item roteado pra uma impressora/setor pode vir tanto de comanda do salão
806	    // (mesa_id/garcom_id preenchidos) quanto de pedido de delivery (produto com a
807	    // mesma impressora configurada) — resolve nome do cliente de delivery à parte
808	    // pra tela poder filtrar e exibir por canal.
809	    const customerIds = [...new Set(itensValidos.map((i) => i.orders?.customer_id).filter(Boolean))];
810	    const { data: customers } = customerIds.length
811	      ? await this.supabase.client.from('customers').select('id, name').in('id', customerIds)
812	      : { data: [] as any[] };
813	    const customerMap = Object.fromEntries((customers ?? []).map((c: any) => [c.id, c.name]));
814	
815	    return {
816	      itens: itensValidos.map((i) => {
817	        const ehSalao = !!(i.orders?.mesa_id || i.orders?.garcom_id || i.orders?.cliente_mesa_nome);
818	        return {
819	          id: i.id,
820	          order_id: i.order_id,
821	          product_name: i.products?.name,
822	          quantity: i.quantity,
823	          observacao: i.observacao,
824	          status: i.status,
825	          enviado_em: i.enviado_em,
826	          preparando_em: i.preparando_em,
827	          pronto_em: i.pronto_em,
828	          entregue_garcom: i.entregue_garcom ?? false,
829	          tipo: ehSalao ? 'salao' : 'delivery',
830	          mesa: i.orders?.mesas ? `Mesa ${i.orders.mesas.numero}${i.orders.mesas.nome ? ' - ' + i.orders.mesas.nome : ''}` : null,
831	          mesa_numero: i.orders?.mesas?.numero ?? null,
832	          numero_comanda: i.orders?.numero_comanda ?? null,
833	          cliente: i.orders?.cliente_mesa_nome ?? (i.orders?.customer_id ? customerMap[i.orders.customer_id] ?? null : null),
834	          garcom: i.orders?.garcons?.nome ?? null,
835	          // Status de entrega do pedido (delivery) — usado no Bar pra alerta de motoboy
836	          // (em trânsito/entregue/ocorrência) e botão de localizar no mapa.
837	          pedido_status: i.orders?.status ?? null,
838	          motoboy_lat: i.orders?.motoboy_lat ?? null,
839	          motoboy_lng: i.orders?.motoboy_lng ?? null,
840	          delivery_occurrence: i.orders?.delivery_occurrence ?? null,
841	        };
842	      }),
843	    };
844	  }
