883	  // Desfaz clique errado na Cozinha/Bar — volta um passo (pronto -> preparando ->
884	  // enviado/aguardando). "Enviado" já é o início da fila do KDS, não dá pra voltar mais.
885	  async voltarStatusItem(itemId: number, restaurantId: number) {
886	    const { data: item } = await this.supabase.client
887	      .from('order_items')
888	      .select('id, status, order_id, orders(restaurant_id)')
889	      .eq('id', itemId)
