891	
892	    if (!item || (item as any).orders?.restaurant_id !== restaurantId) {
893	      throw new NotFoundException('Item não encontrado');
894	    }
895	
896	    if (item.status === 'pronto') {
897	      const { error } = await this.supabase.client
898	        .from('order_items')
899	        .update({ status: 'preparando', pronto_em: null })
900	        .eq('id', itemId);
901	      if (error) throw error;
