917	  private readonly STATUS_ABERTOS = ['pending', 'confirmed', 'preparing', 'ready', 'motoboy_collecting', 'out_for_delivery'];
918	  private readonly COMANDA_STATUS_ABERTOS = ['aberta', 'fechada_garcom'];
919	
920	  // Venda finalizada = entregue (delivery) ou paga (comanda do salão) — sem isso o
921	  // resumo/KPI do dashboard ignorava toda venda do salão (comanda nunca vira 'delivered').
922	  private readonly STATUS_VENDA_FINALIZADA = ['delivered', 'paga'];
923	
924	  // Comanda do salão pode ter N pagamentos com formas diferentes (parcial pelo garçom +
925	  // resto pelo caixa) — orders.payment_method só guarda a última forma usada no
926	  // fechamento, então pra decompor certo o "por forma de pagamento" precisa ir direto
927	  // no ledger de comanda_pagamentos. Delivery continua com pagamento único (sem mudança).
928	  private async buscarPagamentosPorComanda(pedidos: any[]): Promise<Map<number, { order_id: number; valor: number; forma_pagamento: string; origem: string; troco: number; criado_em: string; taxa_cartao_valor: number }[]>> {
929	    const idsComanda = pedidos.filter((p: any) => p.canal === 'presencial').map((p: any) => p.id);
930	    const mapa = new Map<number, { order_id: number; valor: number; forma_pagamento: string; origem: string; troco: number; criado_em: string; taxa_cartao_valor: number }[]>();
931	    if (!idsComanda.length) return mapa;
932	
933	    const { data } = await this.supabase.client
934	      .from('comanda_pagamentos')
935	      .select('order_id, valor, forma_pagamento, origem, troco, criado_em, taxa_cartao_valor')
936	      .in('order_id', idsComanda);
937	
938	    for (const p of (data ?? []) as any[]) {
939	      if (!mapa.has(p.order_id)) mapa.set(p.order_id, []);
940	      mapa.get(p.order_id)!.push({ order_id: p.order_id, valor: p.valor, forma_pagamento: p.forma_pagamento, origem: p.origem, troco: p.troco ?? 0, criado_em: p.criado_em, taxa_cartao_valor: p.taxa_cartao_valor ?? 0 });
941	    }
942	    return mapa;
943	  }
