945	  private calcularResumo(
946	    pedidos: any[],
947	    saidas: any[],
948	    valor_inicial: number,
949	    entradas: any[] = [],
950	    pagamentosPorComanda?: Map<number, { valor: number; forma_pagamento: string; taxa_cartao_valor?: number }[]>,
951	  ) {
952	    const entregues = pedidos.filter((p) => this.STATUS_VENDA_FINALIZADA.includes(p.status));
953	    const total_saidas = saidas.reduce((s: number, e: any) => s + (e.valor ?? 0), 0);
954	    const total_entradas = entradas.reduce((s: number, e: any) => s + (e.valor ?? 0), 0);
955	
956	    // orders.total (comanda do salão) guarda só subtotal-desconto+acréscimo — a taxa de
957	    // cartão cobrada do cliente fica em comanda_pagamentos.taxa_cartao_valor. Entra num
958	    // bucket "taxa_cartao" à parte (não somado dentro de Cartão Crédito/Débito) pra
959	    // aparecer explícito na conferência de fechamento, sem esconder dentro da forma.
960	    let total_vendas = 0;
961	    const por_pagamento: Record<string, number> = {};
962	    // Taxa por forma (não some no bucket único "taxa_cartao") — pra tela de fechamento
963	    // poder mostrar "Débito R$161,70 + taxa R$11,32 = R$173,02" em vez de um total
964	    // de taxa solto, sem saber se veio do débito ou do crédito.
965	    const taxa_por_forma: Record<string, number> = {};
