    if (body.recibo_impressora_id !== undefined) update.recibo_impressora_id = body.recibo_impressora_id;

    const { error } = await this.supabase.client
      .from('restaurants')
      .update(update)
      .eq('id', restaurantId);

    if (error) throw error;
    return this.getConfig(restaurantId);
