8	import Icon from '../../components/AppIcon';
9	
10	// Card por item (não por mesa/comanda) com cronômetro ao vivo — mostra há quanto tempo
11	// o item chegou (aguardando) e, quando em preparo, há quanto tempo está preparando,
12	// pra dar visibilidade do tempo total gasto até ficar pronto.
13	const ItemCard = ({ item, posicao, now, onReimprimir, onIniciarPreparo, onMarcarPronto, onVoltar }) => {
14	  const enviadoEm = new Date(item.enviado_em).getTime();
15	  const preparandoEm = item.preparando_em ? new Date(item.preparando_em).getTime() : null;
16	  const tempoEspera = (preparandoEm ?? now) - enviadoEm;
17	  const tempoPreparo = preparandoEm ? now - preparandoEm : 0;
18	  const tempoTotal = now - enviadoEm;
19	
20	  return (
21	    <div className={`bg-[#1A1A1A] border rounded-2xl overflow-hidden ${posicao === 1 ? 'border-yellow-400/70 ring-1 ring-yellow-400/30' : item.status === 'enviado' ? 'border-blue-500/40' : 'border-[#2A2A2A]'}`}>
22	      {item.garcom && (
23	        <div className="bg-white px-4 py-2">
24	          <p className="text-center text-lg font-black text-[#18181B] uppercase tracking-wide">{item.garcom}</p>
25	        </div>
26	      )}
27	      <div className="p-4">
28	      <div className="flex items-start justify-between mb-1 gap-2">
29	        <div className="flex items-start gap-2">
30	          <span className={`w-6 h-6 flex-shrink-0 rounded-lg flex items-center justify-center text-xs font-black mt-0.5 ${posicao === 1 ? 'bg-yellow-400 text-black' : 'bg-[#2A2A2A] text-white'}`}>
31	            {posicao}
32	          </span>
33	          <div className="leading-tight">
34	            <p className="text-xl font-black text-white">Quantidade: {item.quantity}</p>
35	            <p className="text-lg font-bold text-white">Produto: {item.product_name}</p>
36	          </div>
37	        </div>
38	        <button onClick={() => onReimprimir(item)}
39	          className="text-[10px] font-bold text-orange-400 border border-orange-500/40 rounded-lg px-2 py-1 hover:bg-orange-500/10 flex items-center gap-1 flex-shrink-0">
40	          <Icon name="Printer" size={11} /> Reimpressão
41	        </button>
42	      </div>
43	      {posicao === 1 && <p className="text-[10px] font-bold text-yellow-400 uppercase tracking-wide mb-1">Próximo da fila</p>}
44	      {item.observacao && <p className="text-sm font-bold text-white bg-blue-600 rounded px-1.5 py-0.5 mb-1 animate-pulse">Obs: {item.observacao}</p>}
45	      <div className="flex items-center gap-2 text-base font-bold text-yellow-400 mb-2">
46	        <Icon name="MapPin" size={14} />
47	        <span>{item.mesa ?? item.cliente ?? (item.tipo === 'delivery' ? `Pedido #${item.order_id}` : 'Avulsa')}</span>
48	        {item.numero_comanda && (
49	          <>
50	            <span className="text-[#71717A]">•</span>
51	            <span>Comanda #{item.numero_comanda}</span>
52	          </>
53	        )}
54	        <span className={`ml-auto px-1.5 py-0.5 rounded-full text-[10px] font-bold ${item.tipo === 'delivery' ? 'bg-sky-500/20 text-sky-400' : 'bg-purple-500/20 text-purple-300'}`}>
55	          {item.tipo === 'delivery' ? 'Delivery' : 'Salão'}
56	        </span>
57	      </div>
58	      <div className="flex items-center gap-3 text-[11px] font-mono mb-3">
59	        <span className="flex items-center gap-1 text-blue-400">
60	          <Icon name="Clock" size={11} /> espera {formatDuracao(tempoEspera)}
61	        </span>
62	        {item.status === 'preparando' && (
63	          <span className="flex items-center gap-1 text-orange-400">
64	            <Icon name="Flame" size={11} /> preparo {formatDuracao(tempoPreparo)}
65	          </span>
66	        )}
67	        <span className="ml-auto text-[#71717A]">total {formatDuracao(tempoTotal)}</span>
68	      </div>
69	      <div className="flex gap-2">
70	        {item.status !== 'enviado' && (
71	          <button onClick={() => onVoltar(item)} title="Desfazer — clicou errado"
72	            className="flex-shrink-0 px-3 py-2 bg-[#2A2A2A] hover:bg-[#3A3A3A] text-white text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
73	            <Icon name="Undo2" size={13} /> Voltar
74	          </button>
75	        )}
76	        {item.status === 'enviado' ? (
77	          <button onClick={() => onIniciarPreparo(item)}
78	            className="flex-1 py-2 bg-blue-600 hover:bg-blue-700 text-white text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
79	            <Icon name="ChefHat" size={13} /> Iniciar Preparo
80	          </button>
81	        ) : item.status === 'pronto' ? (
82	          <div className="flex-1 py-2 bg-emerald-900/40 text-emerald-400 text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
83	            <Icon name="Check" size={13} /> {item.entregue_garcom ? 'Entregue pelo garçom' : 'Entregue'}
84	          </div>
85	        ) : (
86	          <button onClick={() => onMarcarPronto(item.id)}
87	            className="flex-1 py-2 bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
88	            <Icon name="Check" size={13} /> Pronto
89	          </button>
90	        )}
91	      </div>
92	      </div>
93	    </div>
94	  );
95	};
96	
97	// Linha de produção do Salão — visão unificada de TODOS os setores (cozinha, bar,
98	// salgados...) num painel só, dono acessa direto logado (sem link/token separado, mesmo
99	// padrão de acesso da tela de Cozinha do delivery). Cada setor é uma impressora
100	// cadastrada; itens vêm de order_items roteados pra ela (ver GET /restaurante/kds),
101	// lista PLANA por item (não agrupa por mesa/comanda), com cronômetro de espera/preparo.
102	const RestauranteProducao = () => {
103	  const navigate = useNavigate();
104	  const [impressoras, setImpressoras] = useState(null);
105	  const [itensPorImpressora, setItensPorImpressora] = useState({});
106	  const [restauranteNome, setRestauranteNome] = useState('');
107	  const [loading, setLoading] = useState(true);
108	  const [erro, setErro] = useState(null);
109	  const [lastUpdate, setLastUpdate] = useState(null);
110	  const now = useNowTick();
111	  const [filtroCanal, setFiltroCanal] = useState('todos'); // 'todos' | 'delivery' | 'salao'
112	  const [verTodosEntregues, setVerTodosEntregues] = useState({}); // { [impressoraId]: bool }
113	  const [busca, setBusca] = useState('');
114	  const prevItemIds = useRef(new Set());
115	  const firstLoad = useRef(true);
116	  const tocarSom = useNotificacaoSonora('cozinha');
117	
118	  useEffect(() => {
119	    getMinhaEmpresa().then((d) => setRestauranteNome(d.empresa?.name ?? '')).catch(() => {});
120	    listarImpressoras().then(setImpressoras).catch((e) => setErro(e.message));
121	  }, []);
122	
123	  const carregar = useCallback(async (lista) => {
124	    try {
125	      const resultados = await Promise.all(
126	        lista.map((imp) => getKdsItensRestaurante(imp.id).then((r) => [imp, r.itens ?? []])),
127	      );
128	      const porImpressora = {};
129	      const idsAgora = new Set();
130	      for (const [imp, itens] of resultados) {
131	        porImpressora[imp.id] = itens;
132	        for (const i of itens) idsAgora.add(i.id);
133	      }
134	
135	      if (!firstLoad.current) {
136	        const novos = [...idsAgora].filter((id) => !prevItemIds.current.has(id));
137	        if (novos.length > 0) tocarSom();
138	      } else {
139	        firstLoad.current = false;
140	      }
141	      prevItemIds.current = idsAgora;
142	
143	      setItensPorImpressora(porImpressora);
144	      setLastUpdate(new Date());
145	      setErro(null);
146	    } catch (e) {
147	      setErro(e.message);
148	    } finally {
149	      setLoading(false);
150	    }
151	  }, [tocarSom]);
152	
153	  useEffect(() => {
154	    if (!impressoras) return;
155	    if (impressoras.length === 0) { setLoading(false); return; }
156	    carregar(impressoras);
157	    const interval = setInterval(() => carregar(impressoras), 15000);
158	    return () => clearInterval(interval);
159	  }, [impressoras, carregar]);
160	
161	  const marcarPronto = async (itemId) => {
162	    await marcarItemProntoRestaurante(itemId);
163	    carregar(impressoras);
164	  };
165	
166	  const iniciarPreparo = async (item) => {
167	    await iniciarPreparoItemRestaurante(item.id);
168	    carregar(impressoras);
169	  };
170	
171	  const voltarItem = async (item) => {
172	    await voltarStatusItemRestaurante(item.id);
173	    carregar(impressoras);
174	  };
175	
176	  const reimprimir = async (item, setorNome) => {
177	    try {
178	      const res = await reimprimirItemRestaurante(item.id);
179	      if (res.via === 'navegador') {
180	        printTicketSetor([item], { mesaLabel: item.mesa, cliente_mesa_nome: item.cliente }, setorNome);
181	      }
182	    } catch (e) {
183	      setErro(e.message);
184	    }
185	  };
186	
187	  if (loading) return (
188	    <div className="min-h-screen bg-[#111111] flex items-center justify-center">
189	      <div className="w-10 h-10 border-4 border-[#FF441F] border-t-transparent rounded-full animate-spin" />
190	    </div>
191	  );
192	
193	  const todosItens = Object.values(itensPorImpressora).flat();
194	  const totalDelivery = todosItens.filter((i) => i.tipo === 'delivery').length;
195	  const totalSalao = todosItens.filter((i) => i.tipo === 'salao').length;
196	  const buscaNormalizada = busca.trim().toLowerCase();
197	  const passaBusca = (i) => {
198	    if (!buscaNormalizada) return true;
199	    const alvo = [i.cliente, i.mesa, i.mesa_numero, i.numero_comanda, i.garcom]
200	      .filter((v) => v !== null && v !== undefined)
201	      .join(' ')
