213	            <Icon name="ArrowLeft" size={18} />
214	          </button>
215	          <div className="flex items-center gap-2">
216	            <div className="w-8 h-8 bg-[#FF441F] rounded-lg flex items-center justify-center flex-shrink-0">
217	              <Icon name="ChefHat" size={16} className="text-white" />
218	            </div>
